    "Messages between Firmware and Boot manager, in order": "ফার্মওয়্যার ও বুট ম্যানেজারের মধ্যে বার্তার ক্রম",
    "Firmware to Boot manager:": "ফার্মওয়্যার থেকে বুট ম্যানেজারে:",
