    "The security guard: checks your password or PIN and keeps your sign-in tokens.": "সাইন-ইনের নিরাপত্তা সামলায়। পাসওয়ার্ড বা PIN যাচাই করে এবং সাইন-ইন টোকেন রাখে।",
