    "you started on HTTPS and stayed there": "শুরু থেকে শেষ পর্যন্ত HTTPS ছিল",
    "it ends on plain HTTP": "শেষে সাধারণ HTTP ব্যবহার হয়েছে",
    "on - browsers will refuse plain HTTP": "চালু, ব্রাউজার সাধারণ HTTP ব্যবহার করতে দেবে না",
    "Web server": "ওয়েব সার্ভার",
    "doesn't say": "জানায়নি",
    "These lists check IPv4 addresses only.": "এই তালিকাগুলো শুধু IPv4 ঠিকানা পরীক্ষা করে।",
    "Type an IPv4 address, like 203.0.113.7": "203.0.113.7-এর মতো একটি IPv4 ঠিকানা লিখুন",
    "No list could be checked": "কোনো তালিকা পরীক্ষা করা যায়নি",
    "None of the lists gave a usable answer just now, so nothing can be said either way. Try again later.": "কোনো তালিকা থেকে এখন কাজে লাগার মতো উত্তর পাওয়া যায়নি। পরে আবার চেষ্টা করুন।",
    "not checked - it doesn't answer public DNS": "পরীক্ষা হয়নি, পাবলিক DNS-এ সাড়া দেয় না",
    "not listed": "তালিকায় নেই",
    "Asked through Google's encrypted DNS. Lists can disagree - each has its own rules.": "Google-এর এনক্রিপ্ট করা DNS দিয়ে খোঁজ নেওয়া হয়েছে। প্রতিটি তালিকার নিয়ম আলাদা, তাই ফলও আলাদা হতে পারে।",
