    "This phone would ask ESPN directly, so ESPN sees its address (as on espn.com). Kept on the phone, a few requests a day.": "ফোনটি সরাসরি ESPN-কে অনুরোধ পাঠায়। espn.com-এর মতো ESPN ফোনের ঠিকানা দেখতে পায়। ফল ফোনে রাখা হয়, তাই দিনে কয়েকবারই অনুরোধ যায়।",
    "Recent results from ESPN's feed, and the day's cricket headlines.": "ESPN-এর সাম্প্রতিক ফল আর আজকের ক্রিকেটের খবর।",
    "The day's headlines - full results on BBC Sport.": "আজকের শিরোনাম। সব ফল BBC Sport-এ।",
    "NBA, NFL, soccer, cricket matches, and headlines. This phone asks ESPN itself, so ESPN sees its address. NHL and MLB come from the leagues through our relay either way.": "NBA, NFL, ফুটবল ও ক্রিকেটের ম্যাচ এবং খবর। ফোনটি সরাসরি ESPN-কে জিজ্ঞেস করে, তাই ESPN এর ঠিকানা দেখতে পায়। NHL ও MLB-এর তথ্য সব সময় লিগ থেকে আমাদের রিলে হয়ে আসে।",
    "Today's free CricketData calls are used up (90 of 100) - back tomorrow.": "আজকের ফ্রি CricketData অনুরোধের সীমা শেষ (১০০টির মধ্যে ৯০টি)। কাল আবার দেখুন।",
    "GNews · your key - opens on each site": "GNews · আপনার কী · খবর নিজ নিজ সাইটে খুলবে",
    "live cricket (100 calls a day - stops at 90)": "লাইভ ক্রিকেট (দিনে ১০০টি অনুরোধ, ৯০টিতে থামে)",
