    "Listed on {hits} of {total}": "{total}টির মধ্যে {hits}টি তালিকায় আছে",
    "Not listed on the {total} lists checked": "পরীক্ষা করা {total}টি তালিকার কোনোটিতেই নেই",
    "listed": "তালিকায় আছে",
    "Mail from this address shouldn't be refused because of these lists.": "এই তালিকাগুলোর কারণে এ ঠিকানা থেকে পাঠানো মেইল আটকে যাওয়ার কথা নয়।",
    "Mail sent straight from this address may be refused or land in spam. On home or mobile data that's common and harmless - your email app sends through its own server. If you run a mail server here, ask each list for removal.": "এই ঠিকানা থেকে সরাসরি পাঠানো মেইল আটকে যেতে পারে বা স্প্যামে যেতে পারে। বাড়ির ইন্টারনেট বা মোবাইল ডেটায় এটা স্বাভাবিক। আপনার মেইল অ্যাপ নিজের সার্ভার দিয়ে পাঠায়। এখানে মেইল সার্ভার চালালে প্রতিটি তালিকা থেকে ঠিকানাটি সরানোর অনুরোধ করুন।",
    "LAST 7 DAYS · THIS PHONE · {count} CHECKS": "গত ৭ দিন · এই ফোন · {count}টি পরীক্ষা",
    "Typical delay {ms} ms": "সাধারণত দেরি {ms} ms",
    "{count} connection checks found real trouble.": "{count}টি সংযোগ পরীক্ষায় সমস্যা ধরা পড়েছে।",
    "1 connection check found real trouble.": "১টি সংযোগ পরীক্ষায় সমস্যা ধরা পড়েছে।",
    "Best around {time}": "{time}-এর দিকে সবচেয়ে ভালো",
    ", slowest around {time}": ", {time}-এর দিকে সবচেয়ে ধীর",
    "Every check you run on this phone adds to it - My connection, Is it down, games, calls. Kept on this phone only, for 7 days.": "এই ফোনে চালানো সংযোগ, সাইট, গেম আর কলের পরীক্ষাগুলো এখানে যোগ হয়। ৭ দিন শুধু এই ফোনে থাকে।",
    "ms, the middle of each day's connection checks. Red: a check that day found real trouble. Days without checks are empty.": "প্রতিদিনের সংযোগ পরীক্ষার মাঝামাঝি মান, ms-এ। লাল মানে সেদিন কোনো পরীক্ষায় সমস্যা ধরা পড়েছে। পরীক্ষা না থাকলে দিনটি ফাঁকা।",
    "BASE64 · {count} BYTES": "BASE64 · {count} বাইট",
    "BASE64 · {count} BYTES OF BINARY": "BASE64 · {count} বাইট বাইনারি ডেটা",
    "All {count} characters.": "সব {count}টি অক্ষর।",
    "The first 4,000 of {count} characters.": "{count}টি অক্ষরের মধ্যে প্রথম ৪,০০০টি।",
    "CERTIFICATE": "সার্টিফিকেট",
    "CERTIFICATE REQUEST": "সার্টিফিকেটের অনুরোধ",
    "Paste -----BEGIN CERTIFICATE-----, a CSR, a JWT (eyJ...) or Base64": "-----BEGIN CERTIFICATE-----, CSR, JWT (eyJ...) বা Base64 পেস্ট করুন",
    "Nothing answered on TCP {port}. Check: the device is on and the app is running, the router forwards {port} to that device, and its firewall allows it. If the router's WAN address starts with 100.64-100.127, your provider uses carrier NAT - ask for a public address.": "TCP পোর্ট {port}-এ সাড়া পাওয়া যায়নি। ডিভাইস ও অ্যাপ চালু আছে কি না দেখুন। রাউটার পোর্ট {port} ওই ডিভাইসে পাঠাচ্ছে এবং ফায়ারওয়াল অনুমতি দিচ্ছে কি না দেখুন। রাউটারের WAN ঠিকানা 100.64-100.127 দিয়ে শুরু হলে সেবাদাতা carrier NAT ব্যবহার করছে। তাদের কাছে একটি পাবলিক ঠিকানা চান।",
    "You're on Cloudflare WARP or a similar service. Turn it off and test again.": "আপনি Cloudflare WARP বা একই ধরনের সেবা ব্যবহার করছেন। সেটি বন্ধ করে আবার পরীক্ষা করুন।",
    "On mobile data this is normal: carriers share one address between many customers (carrier NAT), so nothing can be opened. Test on your home Wi-Fi.": "মোবাইল ডেটায় এটা স্বাভাবিক। সেবাদাতা অনেক গ্রাহকের মধ্যে একটি ঠিকানা ভাগ করে (carrier NAT), তাই পোর্ট খোলা যায় না। বাড়ির Wi-Fi-তে পরীক্ষা করুন।",
    "none, and no address either - mail to @{domain} can't be delivered": "মেইল সার্ভার বা ঠিকানা কোনোটিই নেই। @{domain}-এ মেইল পৌঁছাবে না।",
    "{count} SPF records - only one is allowed; receivers treat it as broken": "{count}টি SPF রেকর্ড আছে। একটি থাকার কথা, তাই প্রাপকের সার্ভার সেটআপটি ভুল ধরে নেবে।",
    "{count} DMARC records - only one is allowed; receivers ignore them all": "{count}টি DMARC রেকর্ড আছে। একটি থাকার কথা, তাই প্রাপকের সার্ভার সবগুলো উপেক্ষা করবে।",
    "missing - anyone can pretend to send as @{domain}": "রেকর্ড নেই। যে কেউ @{domain}-এর নামে মেইল পাঠানোর ভান করতে পারে।",
    "strict (-all): others are refused": "কঠোর (-all): অন্য প্রেরকদের মেইল আটকানো হয়",
    "soft (~all): others are marked as suspicious": "নমনীয় (~all): অন্য প্রেরকদের মেইল সন্দেহজনক হিসেবে চিহ্নিত হয়",
    "neutral (?all): doesn't protect": "নিরপেক্ষ (?all): কোনো সুরক্ষা দেয় না",
    "+all lets anyone send as you - fix it": "+all থাকলে যে কেউ আপনার নামে মেইল পাঠাতে পারে। নিয়মটি ঠিক করুন।",
    "Works, but an MX record is the reliable way to receive mail.": "এভাবে কাজ করে, তবে মেইল পেতে MX রেকর্ড ব্যবহার করাই বেশি নির্ভরযোগ্য।",
